  transitionType "TELEPORT"
}

DEF TV Transform {
  translation 1 0 0
  rotation 0 1 0 0.2
  scale 2 1 1.5
  children DEF O1 OrthoViewpoint {
    fieldOfView -4 -2 4 2
    viewAll TRUE
  }
}

DEF O2 OrthoViewpoint {
  position 3 2 10
  orientation 0 1 0 0.3
  fieldOfView -3 -3 3 3
  viewAll TRUE
  retainUserOffsets TRUE
}

DEF P Viewpoint {
  position 0 0 12
  viewAll TRUE
}

DEF SW Switch {
  children DEF GS Transform {
    scale 0.4 0.4 0.4
    children [
      Transform {
        translation -1.5 0 0
        children Shape {
          appearance Appearance {
            material Material {
              diffuseColor 0.3 0.5 0.9
            }
          }
          geometry Box {
            size 1.5 1.5 1.5
          }
        }
      }
      Transform {
        translation 1.5 0 0
        children Shape {
          appearance Appearance {
            material Material {
              diffuseColor 0.9 0.6 0.2
            }
          }
          geometry Sphere {
            radius 0.9
          }
        }
      }
      DEF FAR Transform {
        translation -9 4 -2
        children Shape {
          appearance Appearance {
            material Material {
              diffuseColor 0.4 0.9 0.4
            }
          }
          geometry Box {
            size 1 1 1
          }
        }
      }
    ]
  }
}

DEF K KeySensor { }

DEF R Script {
  inputOnly      SFString on_key
  inputOutput    SFString log "Ka Kb Kc Kd Ke Kf Kg Kh Ki Kj Kk Kl Km Kn Ko "
  initializeOnly SFNode   o1 USE O1
  initializeOnly SFNode   o2 USE O2
  initializeOnly SFNode   p USE P
  initializeOnly SFNode   gs USE GS
  initializeOnly SFNode   sw USE SW
  initializeOnly SFNode   far USE FAR

  url "javascript:
function on_key (k)
{
   log = log + 'K' + k + ' ';
   if (k == 'a') o1 .viewAll = true;
   if (k == 'b') far .translation = new SFVec3f (-9, 4, -2);
   if (k == 'c') o1 .viewAll = true;
   if (k == 'd') o1 .fieldOfView = new MFFloat (-4, -2, 4, 2);
   if (k == 'e') o1 .viewAll = true;
   if (k == 'f') o1 .viewAll = false;
   if (k == 'g') o2 .set_bind = true;
   if (k == 'h') o2 .viewAll = true;
   if (k == 'i') p .viewAll = true;
   if (k == 'j') p .set_bind = true;
   if (k == 'k') o1 .set_bind = true;
   if (k == 'l') gs .scale = new SFVec3f (0.4, 0.4, 0.4);
   if (k == 'm') o1 .viewAll = true;
   if (k == 'n') sw .whichChoice = -1;
   if (k == 'o') o1 .viewAll = true;
}
"
  directOutput TRUE
}

ROUTE K.keyPress TO R.on_key

